/* ═══════════════════════════════════════════════════════════════
   THE 500 — full action catalog. Shared by Convex backend + UI.
   Fields: c=cost$ e=energy cd=cooldown sec r=risk% lo/hi=reward$ h=heat ± x=xp
   when: rush|concert|wedding|grid  car: needs vehicle  pvp: needs target
   ═══════════════════════════════════════════════════════════════ */

export type CatKey =
  | "street" | "heists" | "vehicles" | "muscle" | "social" | "fronts"
  | "economy" | "gambling" | "smuggling" | "corruption" | "crew"
  | "prison" | "espionage" | "turf" | "lore" | "wild";

export interface ActionDef {
  key: string; cat: CatKey; icon: string; name: string; desc: string;
  cost: number; energy: number; cd: number; risk: number;
  lo: number; hi: number; heat: number; xp: number;
  rep?: number; when?: "rush" | "concert" | "wedding" | "grid";
  car?: boolean; pvp?: boolean;
}
type Opt = { c?: number; e?: number; cd?: number; r?: number; lo?: number; hi?: number; h?: number; x?: number; rep?: number; when?: ActionDef["when"]; car?: boolean; pvp?: boolean };

const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
const A = (cat: CatKey, icon: string, name: string, desc: string, o: Opt = {}): ActionDef => ({
  key: slug(name), cat, icon, name, desc,
  cost: o.c ?? 0, energy: o.e ?? 3, cd: o.cd ?? 120, risk: o.r ?? 10,
  lo: o.lo ?? 100, hi: o.hi ?? 500, heat: o.h ?? 1, xp: o.x ?? 8,
  rep: o.rep, when: o.when, car: o.car, pvp: o.pvp,
});

