export const ACTIONS_BY_KEY: Record<string, ActionDef> = Object.fromEntries(ACTIONS.map((a) => [a.key, a]));
export const ACTIONS_BY_CAT: Record<CatKey, ActionDef[]> = ACTIONS.reduce((acc, a) => {
  (acc[a.cat] ??= []).push(a);
  return acc;
}, {} as Record<CatKey, ActionDef[]>);

export function eventWindowNow(when?: ActionDef["when"], now = Date.now()): boolean {
  if (!when) return true;
  const d = new Date(now);
  const h = d.getHours();
  const min = d.getMinutes();
  switch (when) {
    case "rush": return (h >= 7 && h < 9) || (h >= 16 && h < 18);
    case "concert": return min < 20;
    case "wedding": return d.getDay() === 0;
    case "grid": return min >= 30 && min < 50;
  }
  return true;
}
